/// <summary>
/// The <c>AVAWHSProcessGuidePromptContainerTypeStep</c> class represents the step for container type
/// details and confirming the same.
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuidePromptContainerTypeStep))
]
class AVAWHSProcessGuidePromptContainerTypeStep extends ProcessGuideStep
{
}

Method.Source:
protected final boolean isComplete()
{
    boolean             ret;
    WhsrfPassthrough    pass = controller.parmSessionState().parmPass();

    if (pass.lookupStr(ProcessGuideDataTypeNames::AVAContainerType))
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Executes a suitable step action based on the status.
/// </summary>
protected void executeStepForStatus()
{
    #AVAWHSRF

    WhsrfPassthrough    pass  = controller.parmSessionState().parmPass();
    str                 containerTypeCode;

    if (pass.exists(#AVAContainerType))
    {
        containerTypeCode = pass.lookup(#AVAContainerType);
    }

    if (containerTypeCode != '')
    {
        this.doExecute();

        if (pass.lookupStr(ProcessGuideDataTypeNames::AVASuccessMsg)     )
        {
            this.addCreateLPtMessage();
            pass.remove(ProcessGuideDataTypeNames::AVASuccessMsg);
        }
    }
    else if (this.parmStatus() == ProcessGuideStepStatus::Initialized)
    {
        this.buildPageAndMarkAsWaiting();
    }
    else if (this.parmStatus()  == ProcessGuideStepStatus::WaitingForInput)
    {
        this.executeAction(controller.parmClickedAction());
    }
}

private final void addCreateLPtMessage()
{
    WhsrfPassthrough        pass  = controller.parmSessionState().parmPass();
    ProcessGuideMessageData messageData = ProcessGuideMessageData::construct();


    messageData.message = strFmt(pass.lookupStr(ProcessGuideDataTypeNames::AVASuccessMsg));
    messageData.level   = WHSRFColorText::Success;

    navigationParametersFrom = ProcessGuideNavigationParameters::construct();
    navigationParametersFrom.messageData = messageData;
}
